from lib import *
S = SS('k18')
F1 = [['RequestReceived', '收到请求,尚未处理'], ['处理', '认证 → 鉴权 → 准入 → 写入'], ['ResponseComplete', '响应发完,有状态码']]
F2 = [['Metadata', 'secrets、namespaces:无请求体/响应体'], ['Request', 'pods:有 requestObject'], ['RequestResponse', 'configmaps:两个都有']]
F3 = [['kubectl get pods', '冷缓存'], ['GET /api', '发现'], ['GET /apis', '发现'], ['list pods', '真正的请求']]
F4 = [['kubectl --as nobody', 'user=kubernetes-admin'], ['impersonatedUser', 'system:serviceaccount:k18:nobody'], ['鉴权', 'decision=forbid'], ['403', 'responseStatus.code']]
PANELS = [('f', 'flow', '审计事件'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
PANELS3 = [('f', 'flow', '审计事件'), ('t', 'term', '实测输出'), ('b', 'bars', '请求数'), ('kv', 'kv', '要点')]
steps = [
    step("kubectl create cm c1 时 -v=8 的响应头里有 Audit-Id,用它在审计日志里找到 2 条记录:stage=RequestReceived(没有状态码、没有对象)和 stage=ResponseComplete(code=201,requestObject 与 responseObject 都有)。ResponseComplete 里有 user.username=kubernetes-admin、userAgent=kubectl/v1.36.1、sourceIPs、objectRef,以及 annotations 里的授权决定 allow 和 RBAC 理由。ConfigMap 里的明文口令 hunter2 出现在 requestObject 里;同样的口令放进 Secret,日志里一行都没有(Secret 的规则是 Metadata)。", f=fl(F1, cur=[0, 2], done=[1]), t=tl(S(1), mark=lidx(S(1), 'stage=RequestReceived', 'stage=ResponseComplete', 'requestObject.data'), done=lidx(S(1), '同样的口令 hunter2')), kv=KV([['auditID', '把 RequestReceived 和 ResponseComplete 串起来'], ['annotations', '记录授权决定与理由'], ['RequestResponse 级别', '会把明文 data 写进日志'], ['Secret', '用 Metadata,避免泄漏']], ['RequestResponse 级别'])),
    step("三种级别各创建一个对象:configmaps(RequestResponse)——两个阶段都记,ResponseComplete 里 requestObject 与 responseObject 都有;pods(Request,策略里 omit 了 RequestReceived)——只有 ResponseComplete,有 requestObject、无 responseObject;namespaces(落到最后一条 Metadata 规则)——只有元数据,请求体和响应体都没有。", f=fl(F2, cur=[2], mark=[1], done=[0]), t=tl(S(2), mark=lidx(S(2), 'level=RequestResponse', 'level=Request '), done=lidx(S(2), 'level=Metadata')), kv=KV([['Metadata', '谁在什么时候对什么做了什么'], ['Request', '再加上请求体'], ['RequestResponse', '再加上响应体'], ['omitStages', '可以去掉 RequestReceived 减半日志量']], ['Metadata'])),
    step("一条 kubectl 命令发了多少请求:发现缓存目录为空时 kubectl get pods -n k18 在日志里留下 3 条(GET /api、GET /apis 两个发现请求,加 1 个真正的 list /api/v1/namespaces/k18/pods?limit=500);紧接着再跑一次(缓存已热)只有 1 条 list。k18 的 pods 规则是 Request,但 list 没有请求体,所以 requestObject 是无。", f=fl(F3, cur=[3], done=[1, 2]), t=tl(S(3), mark=lidx(S(3), '冷缓存', '热缓存'), done=lidx(S(3), 'list /api/v1/namespaces/k18/pods')), b=bars([['冷缓存', 3, '3 条'], ['热缓存', 1, '1 条']], 3, mark=[0], done=[1]), kv=KV([['发现请求', '聚合发现:/api 与 /apis 两个就够'], ['缓存', '热了之后只剩真正的请求'], ['审计里的 kubectl', '一条命令 ≠ 一条记录']], ['发现请求'])),
    step("被拒绝的请求也有记录:kubectl get pods --as system:serviceaccount:k18:nobody → Forbidden;日志里 user=kubernetes-admin、impersonatedUser=system:serviceaccount:k18:nobody、code=403、annotations 里 authorization.k8s.io/decision=forbid(reason 为空)。不带令牌的 curl:user=system:anonymous、code=403、decision=forbid。", f=fl(F4, cur=[2], mark=[3], done=[0, 1]), t=tl(S(4), mark=lidx(S(4), 'impersonatedUser=system:serviceaccount', 'user=system:anonymous'), done=lidx(S(4), 'Forbidden')), kv=KV([['--as 模拟', '真实身份在 user,被模拟的在 impersonatedUser'], ['decision', 'allow / forbid'], ['匿名请求', 'user=system:anonymous']], ['--as 模拟'])),
]
A = mkartk('k18', 18, 'Kubernetes,审计日志,Audit,audit policy,RequestResponse,真实验证,动画演示',
    '在单独起的 kind 集群(apiserver 带 --audit-policy-file 与 --audit-log-path)里实测审计日志:一次 kubectl create configmap 留下 RequestReceived 与 ResponseComplete 两条记录,用响应头 Audit-Id 对上,含用户、userAgent、objectRef、授权决定;ConfigMap 在 RequestResponse 级别下口令明文进入日志,Secret 只记元数据;Metadata、Request、RequestResponse 三个级别记录的内容各不相同;冷缓存的 kubectl get pods 留下 3 条请求、热缓存 1 条;被拒绝请求的 decision=forbid,--as 模拟的用户记在 impersonatedUser。',
    '一次 kubectl 命令在 API Server 的审计日志里留下什么?策略里的几个级别到底差在哪?这篇单独起一个开了审计的集群,写一份自己的策略,用 kubectl 响应头里的 Audit-Id 把命令和日志对上,逐字段看一遍,并对比冷热缓存下一条命令发出的请求数。',
    [('2 条', '一次 create configmap 在日志里的记录数:RequestReceived 与 ResponseComplete 共用一个 auditID'), ('hunter2 → 1 行 / 0 行', '同一个口令在 ConfigMap(RequestResponse)和 Secret(Metadata)日志中出现的行数'), ('3 条 vs 1 条', '冷缓存与热缓存时 kubectl get pods 在审计日志里的请求数')],
    [('一次 create 的两条记录', '<p>策略里 k18 命名空间的 ConfigMap 是 <code>RequestResponse</code> 且不 omit 任何阶段,所以一次 <code>kubectl create cm c1</code> 有两条记录,<code>auditID</code> 相同:<code>RequestReceived</code>(还没处理,没有状态码)和 <code>ResponseComplete</code>(<code>code=201</code>,请求体和响应体都在)。后者里能看到 <code>user.username=kubernetes-admin</code>、<code>userAgent=kubectl/v1.36.1</code>、<code>objectRef</code>,以及 <code>annotations</code> 里的授权决定:<code>authorization.k8s.io/decision: allow</code> 和 <code>RBAC: allowed by ClusterRoleBinding "kubeadm:cluster-admins" …</code>。kubectl 的 <code>-v=8</code> 响应头里有同一个 <code>Audit-Id</code>,可以把命令和日志对上。</p><p><code>RequestResponse</code> 把 <code>--from-literal=password=hunter2</code> 的明文写进了 <code>requestObject.data</code>;同样的口令放进 Secret,日志里一行都没有,因为 Secret 的规则是 <code>Metadata</code>。</p>'),
     ('三个级别', '<p>同样是“创建一个对象”:<code>Metadata</code>(namespaces,落到最后一条规则)只记谁、什么时候、对什么、结果如何;<code>Request</code>(pods)再加上 <code>requestObject</code>;<code>RequestResponse</code>(configmaps)再加上 <code>responseObject</code>。pods 和最后一条规则都 <code>omitStages: ["RequestReceived"]</code>,所以只有一条 <code>ResponseComplete</code>——日志量直接少一半。</p>'),
     ('一条命令发多少请求', '<p>发现缓存是空的时,<code>kubectl get pods -n k18</code> 在日志里留下 3 条:<code>GET /api</code>、<code>GET /apis</code>(现代 kubectl 用聚合发现,两个请求就够)和真正的 <code>list /api/v1/namespaces/k18/pods?limit=500</code>;紧接着再跑只有最后 1 条。这个 list 在 pods 的 <code>Request</code> 规则下,但 list 没有请求体,所以 <code>requestObject</code> 为空。分析审计日志时要记得“一条命令”可能对应多条记录。</p>'),
     ('被拒绝与被模拟', '<p>403 同样在日志里:<code>kubectl get pods --as system:serviceaccount:k18:nobody</code> 的记录里 <code>user</code> 仍是真实调用者 <code>kubernetes-admin</code>,被模拟的身份在 <code>impersonatedUser</code>,<code>decision=forbid</code>(<code>reason</code> 为空);不带令牌的 curl 则是 <code>user=system:anonymous</code>、同样 forbid。审计日志是回答“谁尝试过什么”的主要依据。</p>')],
    steps,
    [ENV_K + '。单独起的单节点 kind 集群 kx-audit(Kubernetes v1.37.0),kubeadm 的 ClusterConfiguration 补丁给 kube-apiserver 加了 --audit-policy-file=/etc/kubernetes/policies/audit-policy.yaml 与 --audit-log-path=/var/log/kubernetes/audit.log,策略文件从宿主机挂进节点,日志用 docker exec 读出;策略规则依次是:None(健康检查与 /version)、None(系统组件)、Metadata(secrets)、RequestResponse(k18 的 configmaps)、Request(k18 的 pods,omit RequestReceived)、Metadata(其余,omit RequestReceived);冷缓存实验用空的 KUBECACHEDIR;实验后删除了这个集群;每种情形各一次',
     '没有验证:webhook 后端(--audit-webhook-config-file)与批处理参数;日志轮转(maxage/maxsize/maxbackup);审计对 apiserver 延迟的影响;长连接(watch、exec)的 ResponseStarted 阶段;auditID 在多 apiserver 副本下的关联;策略里 userGroups/verbs/nonResourceURLs 等其他匹配项的完整行为;审计事件里的 stageTimestamp 与耗时分析'],
    '审计事件', PANELS3)
